<?php require 'includes/init.php';$u=require_login();Booking::releaseExpired();$rows=Booking::forUser($u['id']);include 'includes/header.php'; ?>
<main class="page"><div class="wrap"><h2>My Bookings</h2><div class="filters"><span class="chip active">All Bookings</span></div><div class="card"><?php if(!$rows): ?><div class="panel">No bookings yet. <a href="index.php">Book a trip</a>.</div><?php endif; ?><?php foreach($rows as $i=>$b): ?><div class="booking-item"><img src="images/bus <?= (($i%11)+1) ?>.jpg"><div><b><?= e($b['origin'].' → '.$b['destination']) ?></b><div class="meta"><?= date('d M Y | g:i A',strtotime($b['departure_time'])) ?><br><?= e($b['bus_name']) ?> · Seat <?= e($b['seats']) ?></div><span class="status <?= in_array($b['status'],['cancelled','expired'])?'cancel':'' ?>"><?= e(ucfirst($b['status'])) ?></span></div><div><?php if($b['status']==='confirmed'): ?><a href="ticket.php?ref=<?= e($b['booking_ref']) ?>">View Ticket</a><?php elseif($b['status']==='pending'): ?><a href="payment.php?ref=<?= e($b['booking_ref']) ?>">Complete Payment</a><?php endif; ?></div></div><?php endforeach; ?></div></div></main><?php include 'includes/footer.php'; ?>
